clear;
clc;
close all;


load('RadioML2016_mid.mat');


classes5 = {'AM-DSB','BPSK','QAM16','QPSK','WBFM'};

mask = ismember(modulation, classes5);

X5 = X(mask,:,:);
Y5 = modulation(mask);
snr5 = snr(mask);


snrMask = snr5 >= 10;

Xgood = X5(snrMask,:,:);
Ygood = Y5(snrMask);

fprintf('Number of selected signals: %d\n',size(Xgood,1)); %[output:6183b4d9]


Xcnn = permute(Xgood,[3 2 1]);

Xcnn4 = reshape(Xcnn,128,2,1,[]);

Ycnn = categorical(Ygood);


rng(1);

N = size(Xcnn4,4);
order = randperm(N);

nTrain = round(0.8*N);

trainIdx = order(1:nTrain);
testIdx  = order(nTrain+1:end);

XTrainCNN = Xcnn4(:,:,:,trainIdx);
XTestCNN  = Xcnn4(:,:,:,testIdx);

YTrainCNN = Ycnn(trainIdx);
YTestCNN  = Ycnn(testIdx);


XTrainSeq = cell(size(XTrainCNN,4),1);
XTestSeq  = cell(size(XTestCNN,4),1);

for i = 1:size(XTrainCNN,4)
    XTrainSeq{i} = squeeze(XTrainCNN(:,:,1,i))';
end

for i = 1:size(XTestCNN,4)
    XTestSeq{i} = squeeze(XTestCNN(:,:,1,i))';
end


layers1D = [
    sequenceInputLayer(2)

    convolution1dLayer(5,32,'Padding','same')
    batchNormalizationLayer
    reluLayer

    convolution1dLayer(5,64,'Padding','same')
    batchNormalizationLayer
    reluLayer

    globalAveragePooling1dLayer

    fullyConnectedLayer(5)
    softmaxLayer
    classificationLayer
];


options1D = trainingOptions('adam', ...
    'MaxEpochs',20, ...
    'MiniBatchSize',128, ...
    'InitialLearnRate',0.001, ...
    'Shuffle','every-epoch', ...
    'ValidationData',{XTestSeq,YTestCNN}, ...
    'Verbose',true, ...
    'Plots','training-progress');


net1D = trainNetwork(XTrainSeq,YTrainCNN,layers1D,options1D); %[output:049094d5] %[output:9a543457]


YPredCNN = classify(net1D,XTestSeq);

accuracyCNN = mean(YPredCNN == YTestCNN)*100;

fprintf('\nAI Classification Accuracy: %.2f%%\n',accuracyCNN); %[output:83c2a894]


figure; %[output:942f6fb2]

confusionchart(YTestCNN,YPredCNN); %[output:942f6fb2]

title('RF Modulation Classification'); %[output:942f6fb2]


save('RF_Modulation_AI.mat','net1D','classes5');



